'use strict';
function mealState(){const s=prState;s.meal??={filled:false,food:false,loaded:false,drank:false,ate:false};s.guest??='rabbit';return s.meal;}
function mealScene(s){const m=mealState();return prSvg(`${prLandscape()}<ellipse cx="323" cy="211" rx="210" ry="102" fill="#dcb88a" stroke="#a7845c" stroke-width="4"/><path d="M174 270v70M466 269v71" stroke="#a7845c" stroke-width="15" stroke-linecap="round"/>${prFriend(3,99,83,s.guest)}<rect x="32" y="20" width="210" height="67" rx="24" fill="#fffdf3" stroke="#d6dfc6" stroke-width="2"/><path d="M65 86L56 102L91 86" fill="#fffdf3"/>${m.drank&&m.ate?prObject('flower',110,22,61):prObject(m.drank?'cup':'fullcup',66,25,55)+prObject(m.ate?'bowl':'fullbowl',143,25,55)}${m.last==='drink'?prObject('cup',53,158,35):m.last==='eat'?prObject('spoon',52,158,35):''}`);}
function mealRedraw(message=''){prState.message=message;prRender();}
function mealUse(item,target,origin=null){const s=prState,m=mealState();if(target==='tray'){if(origin!==null)s.slots[origin]=null;s.selected=null;s.pickOrigin=null;mealRedraw('Back on the tray, ready to use again.');return;}
 if(target==='bunny'){if(item==='cup'&&m.filled){m.filled=false;m.drank=true;m.last='drink';}else if(item==='spoon'&&m.loaded){m.loaded=false;m.food=false;m.ate=true;m.last='eat';}else{mealRedraw(item==='cup'?'First pour some water into the cup.':item==='spoon'?'First put food in the bowl, then dip the spoon.':'A drink from the cup or a snack on the spoon would help our friend.');return;}s.selected=null;s.pickOrigin=null;mealRedraw(m.drank&&m.ate?'A drink and a snack. You helped your friend!':m.last==='drink'?'A lovely drink. What could help with a snack?':'A tasty snack. What could help with a drink?');return;}
 const i=+target.split(':')[1],there=s.slots[i];if(item==='pitcher'){if(there!=='cup'){mealRedraw('Pour the water into the cup.');return;}m.filled=true;m.last='pour';s.selected=null;mealRedraw('The cup has water. Offer it to your friend.');return;}if(item==='apple'){if(there!=='bowl'){mealRedraw('Put the pretend food into the bowl.');return;}m.food=true;m.last='food';s.selected=null;mealRedraw('Some pretend food for our friend. Dip the spoon into the bowl.');return;}
 if(item==='spoon'&&there==='bowl'&&m.food){m.loaded=true;s.selected=null;s.pickOrigin=null;mealRedraw('A spoonful is ready. Offer the spoon to your friend.');return;}
 if(origin!==null&&origin!==i)s.slots[origin]=null;s.slots[i]=item;s.selected=null;s.pickOrigin=null;mealRedraw(s.slots.every(Boolean)?'The table is ready. Help your friend have a drink and a snack.':'Choose where things go. You can change your mind.');}
function picnicEnhance(root){const s=prState,m=mealState();root.querySelector('.pr-invitation').textContent=m.drank&&m.ate?'Your friend has had a drink and a snack. What a lovely picnic.':'Help your friend have a drink and a snack.';root.querySelector('.pr-board').innerHTML=`<div class="pr-meal-scene">${mealScene(s)}<button class="pr-meal-friend" id="mealFriend" aria-label="Offer a drink or snack to your friend"><span>For our friend</span></button><div class="pr-picnic-slots">${s.slots.map((p,i)=>`<button data-pr-place="${i}" class="${s.selected===p&&s.pickOrigin===i?'pr-meal-selected':''}" aria-label="Table place ${i+1}${p?': '+p:', empty'}">${p?pictureIcon(p==='cup'&&m.filled?'fullcup':p==='bowl'&&m.food?'fullbowl':p):'<span>＋</span>'}${p==='spoon'&&m.loaded?'<span class="meal-spoonful" aria-label="spoonful of pretend food">●</span>':''}</button>`).join('')}</div></div>`;
 const base=['cup','bowl','spoon'].filter(p=>!s.slots.includes(p));root.querySelector('.pr-tools').innerHTML=`<div class="pr-meal-goals"><span class="${m.drank?'done':''}">${m.drank?'✓':'○'} A drink</span><span class="${m.ate?'done':''}">${m.ate?'✓':'○'} A snack</span></div><div class="pr-meal-tools" id="mealTray" aria-label="Picnic tray">${[...base,'pitcher','apple'].map(p=>`<button class="pr-tool ${s.selected===p?'selected':''}" data-pr-picnic="${p}" aria-pressed="${s.selected===p}" aria-label="${p==='pitcher'?'Jug of water':p==='apple'?'Pretend food':nameOf(p)}"><span class="pr-tool-art">${pictureIcon(p==='cup'&&m.filled?'fullcup':p==='bowl'&&m.food?'fullbowl':p)}</span><span>${p==='pitcher'?'Water':p==='apple'?'Food':nameOf(p)}</span></button>`).join('')}</div>${s.selected?'<button class="pr-tool" id="mealPutBack">Put it back</button>':''}${s.slots.every(Boolean)?'<button class="pr-tool" id="prPicnicClear">Set the table again</button>':''}${m.drank&&m.ate?'<button class="pr-tool" id="mealNewFriend">Invite another friend →</button>':''}`;
 root.querySelectorAll('[data-pr-picnic]').forEach(b=>b.onclick=()=>{s.selected=b.dataset.prPicnic;s.pickOrigin=null;mealRedraw(`Choose where the ${s.selected==='pitcher'?'water':s.selected==='apple'?'food':s.selected} should go.`);});root.querySelectorAll('[data-pr-place]').forEach(b=>b.onclick=()=>{const i=+b.dataset.prPlace;if(s.selected)mealUse(s.selected,'slot:'+i,s.pickOrigin??null);else if(s.slots[i]){s.selected=s.slots[i];s.pickOrigin=i;mealRedraw(`Drag the ${s.selected}, or tap where it should go.`);}else mealRedraw('Choose something on the tray, then choose a place.');});root.querySelector('#mealFriend').onclick=()=>s.selected?mealUse(s.selected,'bunny',s.pickOrigin??null):mealRedraw('Offer the filled cup, or a spoonful of food.');root.querySelector('#mealPutBack')?.addEventListener('click',()=>mealUse(s.selected,'tray',s.pickOrigin??null));root.querySelector('#prPicnicClear')?.addEventListener('click',()=>{s.slots=[null,null,null];s.selected=null;s.pickOrigin=null;s.meal={filled:false,food:false,loaded:false,drank:false,ate:false};mealRedraw();});root.querySelector('#mealNewFriend')?.addEventListener('click',()=>{s.guest=s.guest==='rabbit'?'bear':'rabbit';s.meal={filled:false,food:false,loaded:false,drank:false,ate:false};s.selected=null;mealRedraw('Another friend joined the picnic. What would you offer?');});}
function adventureFrame(root){const s=prState;if(root.dataset.adventureReady)return;root.dataset.adventureReady='true';if(s.id==='picnic'){picnicEnhance(root);const instruction=document.createElement('p');instruction.className='tp-instruction';instruction.textContent='Drag an object, or tap it and then tap where it belongs.';root.querySelector('.pr-board').after(instruction);}
 const board=root.querySelector('.pr-board');if(!['picnic','stretch'].includes(s.id)){const hint=document.createElement('p');hint.className='tp-instruction';hint.textContent='Drag pictures into place, or tap to play.';board.after(hint);}
 if(s.id==='garden'){const zone=document.createElement('div');zone.className='pr-garden-drop';zone.id='gardenDrop';zone.setAttribute('aria-label','Garden soil and plant');board.querySelector('.pr-scene-overlay')?.append(zone);if(!board.querySelector('.pr-scene-overlay')){const wrap=document.createElement('div');wrap.className='pr-scene-overlay';wrap.append(...board.childNodes);wrap.append(zone);board.append(wrap);}if(s.step===3){const pick=document.createElement('button');pick.className='pr-tool';pick.id='gardenPick';pick.textContent=s.harvested?'Plant another seed':'Pick a flower for our friend';root.querySelector('.pr-tools').append(pick);pick.onclick=()=>{if(s.harvested){s.step=0;s.harvested=false;s.message='A new seed, a new little garden.';}else{s.harvested=true;s.message='A flower to share. In real life, ask before picking.';}prRender();};if(s.harvested){const gift=document.createElement('div');gift.className='pr-garden-gift';gift.innerHTML=pictureIcon('flower');board.append(gift);}}}
 if(s.id==='bridge'&&s.crossed){const again=document.createElement('button');again.className='pr-tool';again.id='bridgeTrip';again.textContent='Build another way across';root.querySelector('.pr-tools').append(again);again.onclick=()=>{s.bridgeTrip=(s.bridgeTrip||0)+1;s.built=[false,false,false];s.vertical=true;s.crossed=false;s.message='A new little bridge for our friend.';prRender();};}
 if(s.id==='beads'){const wrap=document.createElement('div');wrap.className='pr-scene-overlay';wrap.append(...board.childNodes);const zone=document.createElement('div');zone.className='pr-string-drop';zone.id='beadString';zone.setAttribute('aria-label','Necklace string');wrap.append(zone);const pieces=document.createElement('div');pieces.className='pr-bead-pieces';pieces.innerHTML=s.beads.map((_,i)=>`<button data-bead-piece="${i}" style="left:${(75+i*90-35)/600*100}%" aria-label="Move necklace bead ${i+1}"></button>`).join('');wrap.append(pieces);board.append(wrap);pieces.querySelectorAll('[data-bead-piece]').forEach(b=>b.onclick=()=>{const i=+b.dataset.beadPiece;if(s.beadPick===undefined||s.beadPick===null)s.beadPick=i;else{[s.beads[s.beadPick],s.beads[i]]=[s.beads[i],s.beads[s.beadPick]];s.beadPick=null;}s.message=s.beadPick===null?'The beads swapped. Compare with the picture, or enjoy your own design.':'Choose another bead to swap, or drag this one.';prRender();});}
 if(s.id==='train'&&s.complete){board.classList.add('pr-train-moving');const done=document.createElement('div');done.className='pr-trip-banner';done.textContent=['Next stop: the little garden!','Next stop: a tidy table!','Next stop: the toy workshop!'][s.story%3];root.querySelector('.pr-tools').prepend(done);}
 if(['studio','puppet'].includes(s.id)){const wrap=document.createElement('div');wrap.className='pr-scene-overlay';wrap.append(...board.childNodes);const drop=document.createElement('div');drop.className='pr-stage-drop';drop.id='storyStage';drop.setAttribute('aria-label','Story stage');wrap.append(drop);board.append(wrap);}
 if(s.id==='traffic'){const wrap=document.createElement('div');wrap.className='pr-scene-overlay';wrap.append(...board.childNodes);const zone=document.createElement('div');zone.id='roadDrop';zone.className='pr-road-drop';zone.setAttribute('aria-label','Toy road');const car=document.createElement('button');car.id='roadCar';car.className='tp-move-handle pr-car-handle';car.style.left=(40+s.position*165)/600*100+'%';car.setAttribute('aria-label','Move the toy car');car.onclick=()=>document.querySelector('#prRoadGo')?.click();wrap.append(zone,car);board.append(wrap);}
 if(s.id==='map'){const current=root.querySelector(`[data-pr-step="${s.path.at(-1)}"]`);if(current){current.disabled=false;current.onclick=()=>{s.message='Drag our friend to a nearby stone, or tap the next stone.';prRender();};}}
 if(s.id==='clouds'){s.cloudMoves??={};root.querySelector('#prCloudReset').onclick=()=>{s.removed=[];s.cloudMoves={};s.message='The clouds are back.';prRender();};const wrap=board.querySelector('.pr-scene-overlay');for(const [id,offset]of Object.entries(s.cloudMoves)){const svgCloud=wrap.querySelector(`svg>g[data-cloud-id="${id}"]`);if(svgCloud)svgCloud.setAttribute('transform',`translate(${40+(+id)*165+offset.x} ${75+(+id)%2*90+offset.y})`);const b=wrap.querySelector(`[data-pr-cloud="${id}"]`);if(b){b.style.left=(40+(+id)*165+offset.x)/600*100+'%';b.style.top=(75+(+id)%2*90+offset.y)/360*100+'%';}}}}
TouchPlay.register(bind=>{const root=app.querySelector('.pr-play');if(!root||!prState||prState.paused)return;adventureFrame(root);const s=prState,q=sel=>root.querySelector(sel),qa=sel=>[...root.querySelectorAll(sel)],simple=(src,targets,fn)=>bind(src,{targets,drop:fn});
 if(s.id==='picnic'){const targets=()=>qa('[data-pr-place],#mealFriend,#mealTray');const drop=(item,origin)=>(el)=>mealUse(item,el.id==='mealFriend'?'bunny':el.id==='mealTray'?'tray':'slot:'+el.dataset.prPlace,origin);qa('[data-pr-picnic]').forEach(el=>simple(el,targets,drop(el.dataset.prPicnic,null)));qa('[data-pr-place]').forEach(el=>{const i=+el.dataset.prPlace;if(s.slots[i])simple(el,targets,drop(s.slots[i],i));});}
 if(s.id==='garden')for(const id of ['prPlant','prWater','prDays'])simple(q('#'+id),()=>[q('#gardenDrop')],()=>q('#'+id)?.click());
 if(s.id==='bridge'){simple(q('#prTurn'),()=>qa('[data-pr-plank]'),el=>el.click());qa('[data-pr-plank]').forEach(el=>{const i=+el.dataset.prPlank;if(s.built[i]&&!s.crossed)simple(el,()=>qa('[data-pr-plank]').filter(b=>+b.dataset.prPlank!==i),target=>{const j=+target.dataset.prPlank;[s.built[i],s.built[j]]=[s.built[j],s.built[i]];s.message='You moved a plank.';prRender();});});}
 if(s.id==='beads'){qa('[data-pr-bead]').forEach(el=>simple(el,()=>[q('#beadString')],()=>el.click()));qa('[data-bead-piece]').forEach(el=>{const from=+el.dataset.beadPiece;simple(el,()=>qa('[data-bead-piece]').filter(b=>+b.dataset.beadPiece!==from),target=>{const to=+target.dataset.beadPiece,[piece]=s.beads.splice(from,1);s.beads.splice(to,0,piece);s.beadPick=null;s.message='You moved a bead. Compare with the model, or enjoy your design.';prRender();});});}
 if(s.id==='train')qa('[data-pr-carriage]').forEach(el=>{const from=+el.dataset.prCarriage;simple(el,()=>qa('[data-pr-carriage]').filter(b=>+b.dataset.prCarriage!==from),target=>{const to=+target.dataset.prCarriage;[s.order[from],s.order[to]]=[s.order[to],s.order[from]];s.selected=null;s.complete=false;s.message='The carriages swapped. What happens first?';prRender();});});
 if(['studio','puppet'].includes(s.id))qa('[data-pr-action],[data-pr-actor],[data-pr-place-setting]').forEach(el=>simple(el,()=>[q('#storyStage')],()=>el.click()));
 if(s.id==='drums')qa('[data-pr-drum]').forEach(el=>simple(el,()=>[q('.pr-rhythm')],()=>el.click()));
 if(s.id==='map'){const at=s.path.at(-1);simple(q(`[data-pr-step="${at}"]`),()=>qa('[data-pr-step]:not(:disabled)').filter(el=>+el.dataset.prStep!==at),el=>el.click());}
 if(s.id==='traffic')simple(q('#roadCar'),()=>[q('#roadDrop')],()=>q('#prRoadGo')?.click());
 if(s.id==='clouds')qa('[data-pr-cloud]').forEach(el=>simple(el,()=>[q('.pr-board')],(target,pos)=>{const id=+el.dataset.prCloud,r=target.getBoundingClientRect(),prev=s.cloudMoves[id]||{x:0,y:0};s.cloudMoves[id]={x:prev.x+(pos.x-pos.startX)*600/r.width,y:prev.y+(pos.y-pos.startY)*360/r.height};s.message='You moved a cloud. Make a little space, or simply watch.';prRender();}));});
